/* 字符串-指针-排序函数 */
void stsrt(char *strings [], int num)
{
char *temp;

int top, seek;

for (top = 0; top < num - 1; top++)
for (seek = top + 1; seek < num; seek++)
if (strcmp(strings[top], strings[seek]) > 0)
{
temp = strings[top];
strings[top] = strings[seek];
strings[seek] = temp;
}
}
